        uint32_t a = (uint32_t)rand() * (uint32_t)rand();
        uint32_t b = (uint32_t)rand() * (uint32_t)rand();
        uint32_t err = f_function(a) ^ f_function(b) ^ f_function(a^b) ^ F0;
