        uint32_t b = (uint32_t)rand() * (uint32_t)rand();
        allbits |= f_function(a) ^ f_function(b) ^ f_function(a^b) ^ F0;
    }
    printf("error bits mask: 0x%08X\n", allbits);
    return 0;
}
