#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

uint8_t g_function(uint8_t a, uint8_t b, uint8_t x) {
    uint8_t t = (a + b + x) & 0xFF;
    return ((t << 2) | (t >> 6)) & 0xFF;
}
uint32_t F(uint32_t x) {
    uint8_t x0=x&0xFF, x1=(x>>8)&0xFF, x2=(x>>16)&0xFF, x3=(x>>24)&0xFF;
    uint8_t y2=g_function(x3^x2, x1^x0, 1);
    uint8_t y3=g_function(x3, y2, 0);
    uint8_t y1=g_function(x1^x0, y2, 0);
    uint8_t y0=g_function(x0, y1, 1);
    return (uint32_t)y0|((uint32_t)y1<<8)|((uint32_t)y2<<16)|((uint32_t)y3<<24);
}
uint8_t rot2inv(uint8_t z){ return ((z>>2)|(z<<6))&0xFF; }
uint32_t invF(uint32_t y){
    uint8_t y0=y&0xFF,y1=(y>>8)&0xFF,y2=(y>>16)&0xFF,y3=(y>>24)&0xFF;
    uint8_t x0=rot2inv(y0)-y1;
    uint8_t x1x0=rot2inv(y1)-y2;
    uint8_t x1=x1x0^x0;
    uint8_t x3=rot2inv(y3)-y2;
    uint8_t x3x2=rot2inv(y2)-x1x0-1;
    uint8_t x2=x3^x3x2;
    return (uint32_t)x0|((uint32_t)x1<<8)|((uint32_t)x2<<16)|((uint32_t)x3<<24);
}
uint32_t expand(uint32_t k){ k&=0xFFFFF; return k^(k<<16)^(k*12345); }
uint64_t enc(uint64_t p, const uint32_t*K){
    uint32_t L=p>>32, R=p&0xFFFFFFFF; R^=L;
    for(int i=0;i<4;i++){ uint32_t m=F(R^K[i]); uint32_t t=R; R=L^m; L=t; }
    L^=R; return ((uint64_t)R<<32)|L;
}

#define HSIZE (1u<<21)
static uint32_t hset[HSIZE];
static uint8_t hfull[HSIZE];
static void hset_init(const uint32_t*vals,int n){
    memset(hset,0,sizeof(hset)); memset(hfull,0,sizeof(hfull));
    for(int i=0;i<n;i++){ uint32_t v=vals[i],h=v&(HSIZE-1);
        while(hfull[h]) h=(h+1)&(HSIZE-1); hfull[h]=1; hset[h]=v; }
}
static int hget(uint32_t v){
    uint32_t h=v&(HSIZE-1);
    while(hfull[h]){ if(hset[h]==v) return 1; h=(h+1)&(HSIZE-1); }
    return 0;
}

static uint64_t Cfull; // target ciphertext for verify
static volatile int found=0;
