static int verifyN; static uint64_t* Plist; static uint64_t* Clist;

static void* worker(void*arg){
    (void)arg;
    // split handled by caller via range in arg-less design; we use global ranges
    return 0;
}

int main(int argc,char**argv){
    srand(12345);
    if(argc>=2 && strcmp(argv[1],"test")==0){
        // test mode: small valid set, known key
        int nvalid=1<<16;
        uint32_t* vals=malloc(nvalid*sizeof(uint32_t));
        for(int i=0;i<nvalid;i++) vals[i]=i;
        hset_init(vals,nvalid);
        uint32_t K[4]; for(int i=0;i<4;i++) K[i]=rand()%(1<<16);
        uint64_t P=((uint64_t)rand()<<32)|(uint64_t)rand();
        uint64_t C=enc(P,K);
        uint32_t A=P>>32, B=(P&0xFFFFFFFF)^A, Ch=C>>32, Cl=C&0xFFFFFFFF;
        uint32_t R3=Ch^Cl;
        int ok=0;
        for(int K3=0; K3<nvalid && !ok; K3++){
            uint32_t R2=Ch^F(R3^K3);
            for(int K2=0; K2<nvalid; K2++){
                uint32_t R1=R3^F(R2^K2);
                uint32_t K0=B^invF(A^R1); if(!hget(K0)) continue;
                uint32_t K1=R1^invF(B^R2); if(!hget(K1)) continue;
                if(enc(P,K0,K1,K2,K3)==C){
                    ok=1; printf("recovered K0=%08X K1=%08X K2=%08X K3=%08X\n",K0,K1,K2,K3);
                    printf("expected  K0=%08X K1=%08X K2=%08X K3=%08X\n",K[0],K[1],K[2],K[3]);
                    break;
                }
            }
        }
        if(!ok) printf("FAILED to recover\n");
        // verify invF
        int bad=0; for(int t=0;t<100000;t++){ uint32_t z=rand()*(uint32_t)rand(); if(F(invF(z))!=z||invF(F(z))!=z) bad++; }
        printf("invF errors: %d/100000\n",bad);
        return 0;
    }
    printf("usage: attack test | attack <pairs> [out]\n");
    return 0;
}
