#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

static uint8_t gtab[256][256][2];
static void ginit(){
  for(int a=0;a<256;a++) for(int b=0;b<256;b++){
    uint8_t t=(a+b+1)&0xFF; gtab[a][b][1]=((t<<2)|(t>>6))&0xFF;
    uint8_t u=(a+b)&0xFF; gtab[a][b][0]=((u<<2)|(u>>6))&0xFF;
  }
}
static inline uint32_t F(uint32_t x){
  uint8_t x0=x&0xFF, x1=x>>8, x2=x>>16, x3=x>>24;
  uint8_t y2=gtab[x3^x2][x1^x0][1];
  uint8_t y3=gtab[x3][y2][0];
  uint8_t y1=gtab[x1^x0][y2][0];
  uint8_t y0=gtab[x0][y1][1];
  return y0|((uint32_t)y1<<8)|((uint32_t)y2<<16)|((uint32_t)y3<<24);
}
static inline uint8_t rot2inv(uint8_t z){ return ((z>>2)|(z<<6))&0xFF; }
static inline uint32_t invF(uint32_t y){
  uint8_t y0=y&0xFF, y1=y>>8, y2=y>>16, y3=y>>24;
  uint8_t x0=rot2inv(y0)-y1-1;
  uint8_t x1x0=rot2inv(y1)-y2;
  uint8_t x1=x1x0^x0;
  uint8_t x3=rot2inv(y3)-y2;
  uint8_t x3x2=rot2inv(y2)-x1x0-1;
  uint8_t x2=x3^x3x2;
  return x0|((uint32_t)x1<<8)|((uint32_t)x2<<16)|((uint32_t)x3<<24);
}
static inline uint32_t expand(uint32_t k){ k&=0xFFFFF; return k^(k<<16)^(k*12345); }
static inline uint64_t enc(uint64_t p, const uint32_t*K){
  uint32_t L=p>>32, R=p&0xFFFFFFFF; R^=L;
  for(int i=0;i<4;i++){ uint32_t m=F(R^K[i]); uint32_t t=R; R=L^m; L=t; }
  L^=R; return ((uint64_t)R<<32)|L;
}
static inline uint64_t dec(uint64_t c, const uint32_t*K){
  uint32_t L=c>>32, R=c&0xFFFFFFFF; L^=R;
  for(int i=3;i>=0;i--){ uint32_t m=F(L^K[i]); uint32_t t=L; L=R; R=t; R^=m; }
  R^=L; return ((uint64_t)L<<32)|R;
}

#define HSIZE (1<<22)
static uint32_t hset[HSIZE];
static uint8_t hfull[HSIZE];
static void hset_init(const uint32_t*vals,int n){
  memset(hset,0,sizeof(hset)); memset(hfull,0,sizeof(hfull));
  for(int i=0;i<n;i++){ uint32_t v=vals[i], h=v&(HSIZE-1);
    while(hfull[h]) h=(h+1)&(HSIZE-1);
    hfull[h]=1; hset[h]=v; }
}
static inline int hget(uint32_t v){
  uint32_t h=v&(HSIZE-1);
  while(hfull[h]){ if(hset[h]==v) return 1; h=(h+1)&(HSIZE-1); }
  return 0;
}

static uint32_t *valid_keys;
static const int nvalid = 1 << 20;
static uint64_t gP[32], gC[32];
static int gnPairs;
static volatile int gfound = 0;
static uint32_t gK[4];
static atomic_long gouter = 0;
static const long TOTAL_K3 = 1 << 20;

static void* worker(void* arg){
  long tid = (long)arg;
  const long nthreads = 48;
  long k3_per = nvalid / nthreads;
  long k3_start = tid * k3_per;
  long k3_end = (tid == nthreads-1) ? nvalid : k3_start + k3_per;

  uint32_t A = gP[0] >> 32;
  uint32_t B = (gP[0] & 0xFFFFFFFF) ^ A;
  uint32_t CL = gC[0] & 0xFFFFFFFF;   // CT_low
  uint32_t CR = gC[0] >> 32;          // CT_high
  uint32_t LAP = CL ^ CR;             // X = A^m0^m2

  for(long i3 = k3_start; i3 < k3_end && !gfound; i3++){
    uint32_t K3 = valid_keys[i3];
    uint32_t R2 = CR ^ F(LAP ^ K3);   // R^m1
    uint32_t T3 = invF(B ^ R2);       // invF(m1)

    for(int i2 = 0; i2 < nvalid && !gfound; i2++){
      uint32_t K2 = valid_keys[i2];
      uint32_t L2 = LAP ^ F(R2 ^ K2); // A^m0
      uint32_t K0 = B ^ invF(L2 ^ A);
      uint32_t K1 = L2 ^ T3;

      if(hget(K0) && hget(K1)){
        uint32_t keys[4] = {K0, K1, K2, K3};
        if(enc(gP[0], keys) == gC[0]
           && enc(gP[1], keys) == gC[1]
           && enc(gP[2], keys) == gC[2]){
          // confirm against all pairs
          int ok = 1;
          for(int j=0;j<gnPairs;j++) if(enc(gP[j],keys)!=gC[j]){ ok=0; break; }
          if(ok){
            gK[0]=K0; gK[1]=K1; gK[2]=K2; gK[3]=K3;
            gfound = 1;
            printf("FOUND K0=%08X K1=%08X K2=%08X K3=%08X\n", K0,K1,K2,K3);
            break;
          }
        }
      }
    }
    atomic_fetch_add(&gouter, 1);
  }
  return NULL;
}

static void* monitor(void* arg){
  (void)arg;
  for(int t=0; t<200 && !gfound; t++){
    sleep(5);
    long done = atomic_load(&gouter);
    double pct = 100.0 * done / TOTAL_K3;
    printf("[progress] K3 %.1f%% (%ld/%ld)\n", pct, done, (long)TOTAL_K3);
    fflush(stdout);
  }
  return NULL;
}

int main(){
  ginit();
  FILE *fp = fopen("/app/pairs.txt","r");
  gnPairs = 0;
  unsigned long long p, c;
  while(gnPairs < 32 && fscanf(fp, "%llu %llu", &p, &c) == 2){ gP[gnPairs]=p; gC[gnPairs]=c; gnPairs++; }
  fclose(fp);
  printf("Loaded %d pairs\n", gnPairs);
  fflush(stdout);

  valid_keys = malloc(nvalid * sizeof(uint32_t));
  for(int i = 0; i < nvalid; i++) valid_keys[i] = expand(i);
  hset_init(valid_keys, nvalid);

  printf("Searching 2^40 (K3,K2) pairs across 48 threads (require pairs 0,1,2 match)...\n");
  fflush(stdout);

  pthread_t threads[48], mon;
  for(long t = 0; t < 48; t++) pthread_create(&threads[t], NULL, worker, (void*)t);
  pthread_create(&mon, NULL, monitor, NULL);
  for(long t = 0; t < 48; t++) pthread_join(threads[t], NULL);
  pthread_join(mon, NULL);

  if(!gfound){ printf("Not found\n"); return 1; }

  // Verify against all 32 pairs
  int allok = 1;
  for(int j=0;j<gnPairs;j++) if(enc(gP[j], gK) != gC[j]){ allok=0; printf("MISMATCH pair %d\n", j); }
  printf("Verified against %d pairs: %s\n", gnPairs, allok?"ALL OK":"FAILED");

  int seeds[4];
  for(int i=0;i<4;i++){
    seeds[i]=-1;
    for(int s=0;s<(1<<20);s++) if(expand(s)==gK[i]){ seeds[i]=s; break; }
  }
  for(int i=0;i<4;i++) printf("K%d=0x%08X seed%d=%d (0x%X)\n", i, gK[i], i, seeds[i], seeds[i]);

  FILE *kf = fopen("/app/key.txt","w");
  fprintf(kf, "%X %X %X %X\n", seeds[0], seeds[1], seeds[2], seeds[3]);
  fclose(kf);

  fp = fopen("/app/ciphertexts.txt","r");
  FILE *out = fopen("/app/plaintexts.txt","w");
  unsigned long long cc2; int n=0;
  while(fscanf(fp, "%llu", &cc2) == 1){
    uint64_t pl = dec(cc2, gK);
    fprintf(out, "%llu\n", (unsigned long long)pl);
    n++;
  }
  fclose(fp); fclose(out);
  printf("Decrypted %d ciphertexts to /app/plaintexts.txt\n", n);
  return 0;
}
ENDOFFILE
