static inline uint32_t expand(uint32_t k){ k&=0xFFFFF; return k^(k<<16)^(k*12345); }
static inline uint64_t enc(uint64_t p, const uint32_t*K) {
    uint32_t L=p>>32, R=p&0xFFFFFFFF; R^=L;
    for(int i=0;i<4;i++){ uint32_t m=F(R^K[i]); uint32_t t=R; R=L^m; L=t; }
    L^=R; return ((uint64_t)R<<32)|L;
}
static inline uint64_t dec(uint64_t c, const uint32_t*K) {
    uint32_t L=c>>32, R=c&0xFFFFFFFF; L^=R;
    for(int i=3;i>=0;i--){ uint32_t m=F(L^K[i]); uint32_t t=L; L=R; R=t; R^=m; }
    R^=L; return ((uint64_t)L<<32)|R;
}

#define HSIZE (1<<22)
static uint32_t hset[HSIZE];
static uint8_t hfull[HSIZE];
static void hset_init(const uint32_t*vals,int n){
    memset(hset,0,sizeof(hset)); memset(hfull,0,sizeof(hfull));
    for(int i=0;i<n;i++){ uint32_t v=vals[i], h=v&(HSIZE-1);
        while(hfull[h]) h=(h+1)&(HSIZE-1);
        hfull[h]=1; hset[h]=v; }
}
static inline int hget(uint32_t v){
    uint32_t h=v&(HSIZE-1);
    while(hfull[h]){ if(hset[h]==v) return 1; h=(h+1)&(HSIZE-1); }
    return 0;
}

static const int nvalid = 1 << 20;
static uint32_t valid_keys[nvalid];
static uint32_t precomp[nvalid]; /* precomp[i] = F((B^A)^valid_keys[i]) */
static uint64_t gP[32], gC[32];
static int gnPairs;
static volatile int gfound = 0;
static uint32_t gK[4];
static atomic_long gouter = 0;

static void* worker(void* arg) {
    long tid = (long)arg;
    const long nthreads = 48;
    long k3_per = nvalid / nthreads;
    long k3_start = tid * k3_per;
    long k3_end = (tid == nthreads-1) ? nvalid : k3_start + k3_per;

    uint32_t A = gP[0] >> 32;
    uint32_t B = (gP[0] & 0xFFFFFFFF) ^ A;
    uint32_t CL = gC[0] & 0xFFFFFFFF;
    uint32_t CR = gC[0] >> 32;
    uint32_t R3 = CL ^ CR;
    uint32_t BBA = B ^ A;

    for(long i3 = k3_start; i3 < k3_end && !gfound; i3++) {
        uint32_t K3 = valid_keys[i3];
        uint32_t R2 = CR ^ F(R3 ^ K3);
        uint32_t invR2BA = invF(R2 ^ BBA);

        for(int i0 = 0; i0 < nvalid && !gfound; i0++) {
            uint32_t K0 = valid_keys[i0];
            uint32_t R1 = A ^ precomp[i0];
            uint32_t K1 = R1 ^ invR2BA;
            if(!hget(K1)) continue;
            uint32_t K2 = R2 ^ invF(R3 ^ R1);
            if(!hget(K2)) continue;

            uint32_t keys[4] = {K0, K1, K2, K3};
            if(enc(gP[0], keys) == gC[0]
               && enc(gP[1], keys) == gC[1]
               && enc(gP[2], keys) == gC[2]) {
                int ok = 1;
                for(int j=0;j<gnPairs;j++) if(enc(gP[j],keys)!=gC[j]){ ok=0; break; }
                if(ok) {
                    gK[0]=K0; gK[1]=K1; gK[2]=K2; gK[3]=K3;
                    gfound = 1;
                    printf("FOUND K0=%08X K1=%08X K2=%08X K3=%08X\n", K0,K1,K2,K3);
                    break;
                }
            }
        }
        atomic_fetch_add(&gouter, 1);
    }
    return NULL;
}

static void* monitor(void* arg) {
    (void)arg;
    for(int t=0; t<400 && !gfound; t++) {
        sleep(5);
        long done = atomic_load(&gouter);
        double pct = 100.0 * done / nvalid;
        printf("[progress] K3 %.1f%% (%ld/%d)\n", pct, done, nvalid);
        fflush(stdout);
    }
    return NULL;
}

int main() {
    FILE *fp = fopen("/app/pairs.txt","r");
    gnPairs = 0;
    unsigned long long p, c;
    while(gnPairs < 32 && fscanf(fp, "%llu %llu", &p, &c) == 2) {
        gP[gnPairs]=p; gC[gnPairs]=c; gnPairs++;
    }
    fclose(fp);
    printf("Loaded %d pairs\n", gnPairs);

    uint32_t A = gP[0] >> 32;
    uint32_t B = (gP[0] & 0xFFFFFFFF) ^ A;

    for(int i = 0; i < nvalid; i++) valid_keys[i] = expand(i);
    hset_init(valid_keys, nvalid);

    /* Precompute F((B^A)^K0) for all valid K0 */
    uint32_t BBA = B ^ A;
    for(int i = 0; i < nvalid; i++) precomp[i] = F(BBA ^ valid_keys[i]);
    printf("Precomputed F((B^A)^K0) for %d keys\n", nvalid);

    printf("Searching 2^40 (K3,K0) pairs, 48 threads...\n");
    fflush(stdout);

    pthread_t threads[48], mon;
    for(long t = 0; t < 48; t++) pthread_create(&threads[t], NULL, worker, (void*)t);
    pthread_create(&mon, NULL, monitor, NULL);
    for(long t = 0; t < 48; t++) pthread_join(threads[t], NULL);
    pthread_join(mon, NULL);

    if(!gfound) { printf("Not found\n"); return 1; }

    int allok = 1;
    for(int j=0;j<gnPairs;j++)
        if(enc(gP[j], gK) != gC[j]) { allok=0; printf("MISMATCH pair %d\n", j); }
    printf("Verified %d pairs: %s\n", gnPairs, allok?"ALL OK":"FAILED");

    int seeds[4];
    for(int i=0;i<4;i++) {
        seeds[i]=-1;
        for(int s=0;s<nvalid;s++) if(expand(s)==gK[i]) { seeds[i]=s; break; }
    }
    for(int i=0;i<4;i++)
        printf("K%d=0x%08X seed%d=%d (0x%X)\n", i, gK[i], i, seeds[i], seeds[i]);

    FILE *kf = fopen("/app/key.txt","w");
    fprintf(kf, "%X %X %X %X\n", seeds[0], seeds[1], seeds[2], seeds[3]);
    fclose(kf);

    fp = fopen("/app/ciphertexts.txt","r");
    FILE *out = fopen("/app/plaintexts.txt","w");
    unsigned long long cc2; int n=0;
    while(fscanf(fp, "%llu", &cc2) == 1) {
        uint64_t pl = dec(cc2, gK);
        fprintf(out, "%llu\n", (unsigned long long)pl);
        n++;
    }
    fclose(fp); fclose(out);
    printf("Decrypted %d ciphertexts\n", n);
    return 0;
}
